/** |a - b| <= epsilon. */
fun epsilonEqual(a: Float, b: Float, epsilon: Float = Epsilon): Boolean = (abs((a - b)) <= epsilon)
fun epsilonEqual(a: Double, b: Double, epsilon: Double = DEpsilon): Boolean = (abs((a - b)) <= epsilon)
fun epsilonNotEqual(a: Float, b: Float, epsilon: Float = Epsilon): Boolean = (abs((a - b)) > epsilon)
fun epsilonNotEqual(a: Double, b: Double, epsilon: Double = DEpsilon): Boolean = (abs((a - b)) > epsilon)
fun epsilonEqual(a: Vec2, b: Vec2, epsilon: Float = Epsilon): BVec2 = BVec2((abs((a.x - b.x)) <= epsilon), (abs((a.y - b.y)) <= epsilon))
fun epsilonEqual(a: DVec2, b: DVec2, epsilon: Double = DEpsilon): BVec2 = BVec2((abs((a.x - b.x)) <= epsilon), (abs((a.y - b.y)) <= epsilon))
fun epsilonEqual(a: Vec3, b: Vec3, epsilon: Float = Epsilon): BVec3 = BVec3((abs((a.x - b.x)) <= epsilon), (abs((a.y - b.y)) <= epsilon), (abs((a.z - b.z)) <= epsilon))
fun epsilonEqual(a: DVec3, b: DVec3, epsilon: Double = DEpsilon): BVec3 = BVec3((abs((a.x - b.x)) <= epsilon), (abs((a.y - b.y)) <= epsilon), (abs((a.z - b.z)) <= epsilon))
fun epsilonEqual(a: Vec4, b: Vec4, epsilon: Float = Epsilon): BVec4 = BVec4((abs((a.x - b.x)) <= epsilon), (abs((a.y - b.y)) <= epsilon), (abs((a.z - b.z)) <= epsilon), (abs((a.w - b.w)) <= epsilon))
fun epsilonEqual(a: DVec4, b: DVec4, epsilon: Double = DEpsilon): BVec4 = BVec4((abs((a.x - b.x)) <= epsilon), (abs((a.y - b.y)) <= epsilon), (abs((a.z - b.z)) <= epsilon), (abs((a.w - b.w)) <= epsilon))
fun epsilonNotEqual(a: Vec2, b: Vec2, epsilon: Float = Epsilon): BVec2 = not(epsilonEqual(a, b, epsilon))
fun epsilonNotEqual(a: Vec3, b: Vec3, epsilon: Float = Epsilon): BVec3 = not(epsilonEqual(a, b, epsilon))
fun epsilonNotEqual(a: Vec4, b: Vec4, epsilon: Float = Epsilon): BVec4 = not(epsilonEqual(a, b, epsilon))
fun epsilonNotEqual(a: DVec2, b: DVec2, epsilon: Double = DEpsilon): BVec2 = not(epsilonEqual(a, b, epsilon))
fun epsilonNotEqual(a: DVec3, b: DVec3, epsilon: Double = DEpsilon): BVec3 = not(epsilonEqual(a, b, epsilon))
fun epsilonNotEqual(a: DVec4, b: DVec4, epsilon: Double = DEpsilon): BVec4 = not(epsilonEqual(a, b, epsilon))
/** Within epsilon: one bool, for checks and tests. */
fun approxEqual(a: Float, b: Float, epsilon: Float = Epsilon): Boolean = (abs((a - b)) <= epsilon)
fun approxEqual(a: Double, b: Double, epsilon: Double = DEpsilon): Boolean = (abs((a - b)) <= epsilon)
fun approxEqual(a: Vec2, b: Vec2, epsilon: Float = Epsilon): Boolean = all(epsilonEqual(a, b, epsilon))
fun approxEqual(a: Vec3, b: Vec3, epsilon: Float = Epsilon): Boolean = all(epsilonEqual(a, b, epsilon))
fun approxEqual(a: Vec4, b: Vec4, epsilon: Float = Epsilon): Boolean = all(epsilonEqual(a, b, epsilon))
fun approxEqual(a: DVec2, b: DVec2, epsilon: Double = DEpsilon): Boolean = all(epsilonEqual(a, b, epsilon))
fun approxEqual(a: DVec3, b: DVec3, epsilon: Double = DEpsilon): Boolean = all(epsilonEqual(a, b, epsilon))
fun approxEqual(a: DVec4, b: DVec4, epsilon: Double = DEpsilon): Boolean = all(epsilonEqual(a, b, epsilon))

// ---- integer (GLSL 8.8, glm's integer.hpp, ext/scalar_integer, gtc/round) ------------------------------------

/** How many bits are set. */
fun bitCount(v: Int): Int = v.countOneBits()
fun bitCount(v: IVec2): IVec2 = IVec2(bitCount(v.x), bitCount(v.y))
fun bitCount(v: IVec3): IVec3 = IVec3(bitCount(v.x), bitCount(v.y), bitCount(v.z))
fun bitCount(v: IVec4): IVec4 = IVec4(bitCount(v.x), bitCount(v.y), bitCount(v.z), bitCount(v.w))
fun bitCount(v: UInt): Int = v.countOneBits()
fun bitCount(v: UVec2): IVec2 = IVec2(bitCount(v.x), bitCount(v.y))
fun bitCount(v: UVec3): IVec3 = IVec3(bitCount(v.x), bitCount(v.y), bitCount(v.z))
fun bitCount(v: UVec4): IVec4 = IVec4(bitCount(v.x), bitCount(v.y), bitCount(v.z), bitCount(v.w))
/** The lowest set bit's index; -1 for 0. */
fun findLSB(v: Int): Int = if (v == 0) -1 else v.countTrailingZeroBits()
fun findLSB(v: IVec2): IVec2 = IVec2(findLSB(v.x), findLSB(v.y))
fun findLSB(v: IVec3): IVec3 = IVec3(findLSB(v.x), findLSB(v.y), findLSB(v.z))
fun findLSB(v: IVec4): IVec4 = IVec4(findLSB(v.x), findLSB(v.y), findLSB(v.z), findLSB(v.w))
fun findLSB(v: UInt): Int = if (v == 0u) -1 else v.countTrailingZeroBits()
fun findLSB(v: UVec2): IVec2 = IVec2(findLSB(v.x), findLSB(v.y))
fun findLSB(v: UVec3): IVec3 = IVec3(findLSB(v.x), findLSB(v.y), findLSB(v.z))
fun findLSB(v: UVec4): IVec4 = IVec4(findLSB(v.x), findLSB(v.y), findLSB(v.z), findLSB(v.w))
/** The highest set bit's index; -1 for 0. For a negative value: the highest bit that is 0. */
fun findMSB(v: Int): Int {
    val u = if (v < 0) v.inv() else v
    return if (u == 0) -1 else 31 - u.countLeadingZeroBits()
}
fun findMSB(v: IVec2): IVec2 = IVec2(findMSB(v.x), findMSB(v.y))
fun findMSB(v: IVec3): IVec3 = IVec3(findMSB(v.x), findMSB(v.y), findMSB(v.z))
fun findMSB(v: IVec4): IVec4 = IVec4(findMSB(v.x), findMSB(v.y), findMSB(v.z), findMSB(v.w))
fun findMSB(v: UInt): Int = if (v == 0u) -1 else 31 - v.countLeadingZeroBits()
fun findMSB(v: UVec2): IVec2 = IVec2(findMSB(v.x), findMSB(v.y))
fun findMSB(v: UVec3): IVec3 = IVec3(findMSB(v.x), findMSB(v.y), findMSB(v.z))
fun findMSB(v: UVec4): IVec4 = IVec4(findMSB(v.x), findMSB(v.y), findMSB(v.z), findMSB(v.w))
/** bits bits of v from bit offset, at the bottom of the result: sign-extended for a signed type. */
fun bitfieldExtract(v: Int, offset: Int, bits: Int): Int {
    if (bits <= 0) return 0
    val u = v.toUInt()
    val f = if (bits >= 32) u shr offset else (u shr offset) and ((1u shl bits) - 1u)
    if (bits < 32 && ((f shr (bits - 1)) and 1u) != 0u) return (f or ((1u shl bits) - 1u).inv()).toInt()
    return f.toInt()
}
fun bitfieldExtract(v: IVec2, offset: Int, bits: Int): IVec2 = IVec2(bitfieldExtract(v.x, offset, bits), bitfieldExtract(v.y, offset, bits))
fun bitfieldExtract(v: IVec3, offset: Int, bits: Int): IVec3 = IVec3(bitfieldExtract(v.x, offset, bits), bitfieldExtract(v.y, offset, bits), bitfieldExtract(v.z, offset, bits))
fun bitfieldExtract(v: IVec4, offset: Int, bits: Int): IVec4 = IVec4(bitfieldExtract(v.x, offset, bits), bitfieldExtract(v.y, offset, bits), bitfieldExtract(v.z, offset, bits), bitfieldExtract(v.w, offset, bits))
fun bitfieldExtract(v: UInt, offset: Int, bits: Int): UInt {
    if (bits <= 0) return 0u
    return if (bits >= 32) v shr offset else (v shr offset) and ((1u shl bits) - 1u)
}
fun bitfieldExtract(v: UVec2, offset: Int, bits: Int): UVec2 = UVec2(bitfieldExtract(v.x, offset, bits), bitfieldExtract(v.y, offset, bits))
fun bitfieldExtract(v: UVec3, offset: Int, bits: Int): UVec3 = UVec3(bitfieldExtract(v.x, offset, bits), bitfieldExtract(v.y, offset, bits), bitfieldExtract(v.z, offset, bits))
fun bitfieldExtract(v: UVec4, offset: Int, bits: Int): UVec4 = UVec4(bitfieldExtract(v.x, offset, bits), bitfieldExtract(v.y, offset, bits), bitfieldExtract(v.z, offset, bits), bitfieldExtract(v.w, offset, bits))
/** base with bits bits from bit offset replaced by the low bits of insert. */
fun bitfieldInsert(base: Int, insert: Int, offset: Int, bits: Int): Int {
    if (bits <= 0) return base
    val low = if (bits >= 32) 0u.inv() else (1u shl bits) - 1u
    val mask = low shl offset
    return ((base.toUInt() and mask.inv()) or ((insert.toUInt() shl offset) and mask)).toInt()
}
fun bitfieldInsert(base: IVec2, insert: IVec2, offset: Int, bits: Int): IVec2 = IVec2(bitfieldInsert(base.x, insert.x, offset, bits), bitfieldInsert(base.y, insert.y, offset, bits))
fun bitfieldInsert(base: IVec3, insert: IVec3, offset: Int, bits: Int): IVec3 = IVec3(bitfieldInsert(base.x, insert.x, offset, bits), bitfieldInsert(base.y, insert.y, offset, bits), bitfieldInsert(base.z, insert.z, offset, bits))
fun bitfieldInsert(base: IVec4, insert: IVec4, offset: Int, bits: Int): IVec4 = IVec4(bitfieldInsert(base.x, insert.x, offset, bits), bitfieldInsert(base.y, insert.y, offset, bits), bitfieldInsert(base.z, insert.z, offset, bits), bitfieldInsert(base.w, insert.w, offset, bits))
fun bitfieldInsert(base: UInt, insert: UInt, offset: Int, bits: Int): UInt {
    if (bits <= 0) return base
    val low = if (bits >= 32) 0u.inv() else (1u shl bits) - 1u
    val mask = low shl offset
    return ((base.toUInt() and mask.inv()) or ((insert.toUInt() shl offset) and mask)).toUInt()
}
fun bitfieldInsert(base: UVec2, insert: UVec2, offset: Int, bits: Int): UVec2 = UVec2(bitfieldInsert(base.x, insert.x, offset, bits), bitfieldInsert(base.y, insert.y, offset, bits))
fun bitfieldInsert(base: UVec3, insert: UVec3, offset: Int, bits: Int): UVec3 = UVec3(bitfieldInsert(base.x, insert.x, offset, bits), bitfieldInsert(base.y, insert.y, offset, bits), bitfieldInsert(base.z, insert.z, offset, bits))
