/** The bits in reverse order. */
fun bitfieldReverse(v: Int): Int {
    var u = v.toUInt()
    var r = 0u
    repeat(32) { r = (r shl 1) or (u and 1u); u = u shr 1 }
    return r.toInt()
}
fun bitfieldReverse(v: IVec2): IVec2 = IVec2(bitfieldReverse(v.x), bitfieldReverse(v.y))
fun bitfieldReverse(v: IVec3): IVec3 = IVec3(bitfieldReverse(v.x), bitfieldReverse(v.y), bitfieldReverse(v.z))
fun bitfieldReverse(v: IVec4): IVec4 = IVec4(bitfieldReverse(v.x), bitfieldReverse(v.y), bitfieldReverse(v.z), bitfieldReverse(v.w))
fun bitfieldReverse(v: UInt): UInt {
    var u = v.toUInt()
    var r = 0u
    repeat(32) { r = (r shl 1) or (u and 1u); u = u shr 1 }
    return r.toUInt()
}
fun bitfieldReverse(v: UVec2): UVec2 = UVec2(bitfieldReverse(v.x), bitfieldReverse(v.y))
fun bitfieldReverse(v: UVec3): UVec3 = UVec3(bitfieldReverse(v.x), bitfieldReverse(v.y), bitfieldReverse(v.z))
fun bitfieldReverse(v: UVec4): UVec4 = UVec4(bitfieldReverse(v.x), bitfieldReverse(v.y), bitfieldReverse(v.z), bitfieldReverse(v.w))
/** x + y, and in carry whether it overflowed. */
fun uaddCarry(x: UInt, y: UInt, carry: Ref<UInt>): UInt {
    val s = x + y
    carry.value = if (s < x) 1u else 0u
    return s
}
fun uaddCarry(x: UVec2, y: UVec2, carry: Ref<UVec2>): UVec2 {
    val carryX = Ref(0u)
    val carryY = Ref(0u)
    val r = UVec2(uaddCarry(x.x, y.x, carryX), uaddCarry(x.y, y.y, carryY))
    carry.value = UVec2(carryX.value, carryY.value)
    return r
}
fun uaddCarry(x: UVec3, y: UVec3, carry: Ref<UVec3>): UVec3 {
    val carryX = Ref(0u)
    val carryY = Ref(0u)
    val carryZ = Ref(0u)
    val r = UVec3(uaddCarry(x.x, y.x, carryX), uaddCarry(x.y, y.y, carryY), uaddCarry(x.z, y.z, carryZ))
    carry.value = UVec3(carryX.value, carryY.value, carryZ.value)
    return r
}
fun uaddCarry(x: UVec4, y: UVec4, carry: Ref<UVec4>): UVec4 {
    val carryX = Ref(0u)
    val carryY = Ref(0u)
    val carryZ = Ref(0u)
    val carryW = Ref(0u)
    val r = UVec4(uaddCarry(x.x, y.x, carryX), uaddCarry(x.y, y.y, carryY), uaddCarry(x.z, y.z, carryZ), uaddCarry(x.w, y.w, carryW))
    carry.value = UVec4(carryX.value, carryY.value, carryZ.value, carryW.value)
    return r
}
/** x - y, and in borrow whether it went below zero. */
fun usubBorrow(x: UInt, y: UInt, borrow: Ref<UInt>): UInt {
    borrow.value = if (x < y) 1u else 0u
    return x - y
}
fun usubBorrow(x: UVec2, y: UVec2, borrow: Ref<UVec2>): UVec2 {
    val borrowX = Ref(0u)
    val borrowY = Ref(0u)
    val r = UVec2(usubBorrow(x.x, y.x, borrowX), usubBorrow(x.y, y.y, borrowY))
    borrow.value = UVec2(borrowX.value, borrowY.value)
    return r
}
fun usubBorrow(x: UVec3, y: UVec3, borrow: Ref<UVec3>): UVec3 {
    val borrowX = Ref(0u)
    val borrowY = Ref(0u)
    val borrowZ = Ref(0u)
    val r = UVec3(usubBorrow(x.x, y.x, borrowX), usubBorrow(x.y, y.y, borrowY), usubBorrow(x.z, y.z, borrowZ))
    borrow.value = UVec3(borrowX.value, borrowY.value, borrowZ.value)
    return r
}
fun usubBorrow(x: UVec4, y: UVec4, borrow: Ref<UVec4>): UVec4 {
    val borrowX = Ref(0u)
    val borrowY = Ref(0u)
    val borrowZ = Ref(0u)
    val borrowW = Ref(0u)
    val r = UVec4(usubBorrow(x.x, y.x, borrowX), usubBorrow(x.y, y.y, borrowY), usubBorrow(x.z, y.z, borrowZ), usubBorrow(x.w, y.w, borrowW))
    borrow.value = UVec4(borrowX.value, borrowY.value, borrowZ.value, borrowW.value)
    return r
}
/** The 64-bit product, its high and low halves. */
fun umulExtended(x: UInt, y: UInt, msb: Ref<UInt>, lsb: Ref<UInt>): Unit {
    val p = x.toULong() * y.toULong()
    msb.value = (p shr 32).toUInt()
    lsb.value = p.toUInt()
}
fun umulExtended(x: UVec2, y: UVec2, msb: Ref<UVec2>, lsb: Ref<UVec2>): Unit {
    val msbX = Ref(0u)
    val msbY = Ref(0u)
    val lsbX = Ref(0u)
    val lsbY = Ref(0u)
    umulExtended(x.x, y.x, msbX, lsbX)
    umulExtended(x.y, y.y, msbY, lsbY)
    msb.value = UVec2(msbX.value, msbY.value)
    lsb.value = UVec2(lsbX.value, lsbY.value)
}
fun umulExtended(x: UVec3, y: UVec3, msb: Ref<UVec3>, lsb: Ref<UVec3>): Unit {
    val msbX = Ref(0u)
    val msbY = Ref(0u)
    val msbZ = Ref(0u)
    val lsbX = Ref(0u)
    val lsbY = Ref(0u)
    val lsbZ = Ref(0u)
    umulExtended(x.x, y.x, msbX, lsbX)
    umulExtended(x.y, y.y, msbY, lsbY)
    umulExtended(x.z, y.z, msbZ, lsbZ)
    msb.value = UVec3(msbX.value, msbY.value, msbZ.value)
    lsb.value = UVec3(lsbX.value, lsbY.value, lsbZ.value)
}
fun umulExtended(x: UVec4, y: UVec4, msb: Ref<UVec4>, lsb: Ref<UVec4>): Unit {
    val msbX = Ref(0u)
    val msbY = Ref(0u)
    val msbZ = Ref(0u)
    val msbW = Ref(0u)
    val lsbX = Ref(0u)
    val lsbY = Ref(0u)
    val lsbZ = Ref(0u)
    val lsbW = Ref(0u)
    umulExtended(x.x, y.x, msbX, lsbX)
    umulExtended(x.y, y.y, msbY, lsbY)
    umulExtended(x.z, y.z, msbZ, lsbZ)
    umulExtended(x.w, y.w, msbW, lsbW)
    msb.value = UVec4(msbX.value, msbY.value, msbZ.value, msbW.value)
    lsb.value = UVec4(lsbX.value, lsbY.value, lsbZ.value, lsbW.value)
}
fun imulExtended(x: Int, y: Int, msb: Ref<Int>, lsb: Ref<Int>): Unit {
    val p = x.toLong() * y.toLong()
    msb.value = (p shr 32).toInt()
    lsb.value = p.toInt()
}
