fun isPowerOfTwo(v: Int): Boolean = ((v > 0) && ((v and (v - 1)) == 0))
fun isPowerOfTwo(v: IVec2): BVec2 = BVec2(isPowerOfTwo(v.x), isPowerOfTwo(v.y))
fun isPowerOfTwo(v: IVec3): BVec3 = BVec3(isPowerOfTwo(v.x), isPowerOfTwo(v.y), isPowerOfTwo(v.z))
fun isPowerOfTwo(v: IVec4): BVec4 = BVec4(isPowerOfTwo(v.x), isPowerOfTwo(v.y), isPowerOfTwo(v.z), isPowerOfTwo(v.w))
fun isPowerOfTwo(v: UInt): Boolean = ((v > 0u) && ((v and (v - 1u)) == 0u))
fun isPowerOfTwo(v: UVec2): BVec2 = BVec2(isPowerOfTwo(v.x), isPowerOfTwo(v.y))
fun isPowerOfTwo(v: UVec3): BVec3 = BVec3(isPowerOfTwo(v.x), isPowerOfTwo(v.y), isPowerOfTwo(v.z))
fun isPowerOfTwo(v: UVec4): BVec4 = BVec4(isPowerOfTwo(v.x), isPowerOfTwo(v.y), isPowerOfTwo(v.z), isPowerOfTwo(v.w))
/** The smallest power of two >= v (1 for 0 and below). */
fun ceilPowerOfTwo(v: Int): Int = if (v <= 1) 1 else Integer.highestOneBit(v - 1) shl 1
fun ceilPowerOfTwo(v: IVec2): IVec2 = IVec2(ceilPowerOfTwo(v.x), ceilPowerOfTwo(v.y))
fun ceilPowerOfTwo(v: IVec3): IVec3 = IVec3(ceilPowerOfTwo(v.x), ceilPowerOfTwo(v.y), ceilPowerOfTwo(v.z))
fun ceilPowerOfTwo(v: IVec4): IVec4 = IVec4(ceilPowerOfTwo(v.x), ceilPowerOfTwo(v.y), ceilPowerOfTwo(v.z), ceilPowerOfTwo(v.w))
fun ceilPowerOfTwo(v: UInt): UInt = if (v <= 1u) 1u else (Integer.highestOneBit((v - 1u).toInt()) shl 1).toUInt()
fun ceilPowerOfTwo(v: UVec2): UVec2 = UVec2(ceilPowerOfTwo(v.x), ceilPowerOfTwo(v.y))
fun ceilPowerOfTwo(v: UVec3): UVec3 = UVec3(ceilPowerOfTwo(v.x), ceilPowerOfTwo(v.y), ceilPowerOfTwo(v.z))
fun ceilPowerOfTwo(v: UVec4): UVec4 = UVec4(ceilPowerOfTwo(v.x), ceilPowerOfTwo(v.y), ceilPowerOfTwo(v.z), ceilPowerOfTwo(v.w))
/** The largest power of two <= v (0 for 0 and below). */
fun floorPowerOfTwo(v: Int): Int = if (v <= 0) 0 else Integer.highestOneBit(v)
fun floorPowerOfTwo(v: IVec2): IVec2 = IVec2(floorPowerOfTwo(v.x), floorPowerOfTwo(v.y))
fun floorPowerOfTwo(v: IVec3): IVec3 = IVec3(floorPowerOfTwo(v.x), floorPowerOfTwo(v.y), floorPowerOfTwo(v.z))
fun floorPowerOfTwo(v: IVec4): IVec4 = IVec4(floorPowerOfTwo(v.x), floorPowerOfTwo(v.y), floorPowerOfTwo(v.z), floorPowerOfTwo(v.w))
fun floorPowerOfTwo(v: UInt): UInt = if (v == 0u) 0u else Integer.highestOneBit(v.toInt()).toUInt()
fun floorPowerOfTwo(v: UVec2): UVec2 = UVec2(floorPowerOfTwo(v.x), floorPowerOfTwo(v.y))
fun floorPowerOfTwo(v: UVec3): UVec3 = UVec3(floorPowerOfTwo(v.x), floorPowerOfTwo(v.y), floorPowerOfTwo(v.z))
fun floorPowerOfTwo(v: UVec4): UVec4 = UVec4(floorPowerOfTwo(v.x), floorPowerOfTwo(v.y), floorPowerOfTwo(v.z), floorPowerOfTwo(v.w))
/** The nearest power of two (the larger, halfway between two). */
fun roundPowerOfTwo(v: Int): Int {
    val up = ceilPowerOfTwo(v)
    val down = floorPowerOfTwo(v)
    return (if (((up - v) <= (v - down))) up else down)
}
fun roundPowerOfTwo(v: IVec2): IVec2 = IVec2(roundPowerOfTwo(v.x), roundPowerOfTwo(v.y))
fun roundPowerOfTwo(v: IVec3): IVec3 = IVec3(roundPowerOfTwo(v.x), roundPowerOfTwo(v.y), roundPowerOfTwo(v.z))
fun roundPowerOfTwo(v: IVec4): IVec4 = IVec4(roundPowerOfTwo(v.x), roundPowerOfTwo(v.y), roundPowerOfTwo(v.z), roundPowerOfTwo(v.w))
fun roundPowerOfTwo(v: UInt): UInt {
    val up = ceilPowerOfTwo(v)
    val down = floorPowerOfTwo(v)
    return (if (((up - v) <= (v - down))) up else down)
}
fun roundPowerOfTwo(v: UVec2): UVec2 = UVec2(roundPowerOfTwo(v.x), roundPowerOfTwo(v.y))
fun roundPowerOfTwo(v: UVec3): UVec3 = UVec3(roundPowerOfTwo(v.x), roundPowerOfTwo(v.y), roundPowerOfTwo(v.z))
fun roundPowerOfTwo(v: UVec4): UVec4 = UVec4(roundPowerOfTwo(v.x), roundPowerOfTwo(v.y), roundPowerOfTwo(v.z), roundPowerOfTwo(v.w))
