// ---- packing (GLSL 8.4, glm's packing.hpp) -------------------------------------------------------------------

/** IEEE half precision, round to nearest even; overflow becomes infinity, NaN stays NaN. */
fun floatToHalf(value: Float): UShort {
    val bits = value.toRawBits().toUInt()
    val sign = (bits shr 16) and 0x8000u
    val exponent = (bits shr 23) and 0xffu
    var mantissa = bits and 0x7fffffu
    if (exponent == 0xffu) return (sign or 0x7c00u or (if (mantissa != 0u) 0x200u else 0u)).toUShort()
    val e = exponent.toInt() - 127 + 15
    if (e >= 31) return (sign or 0x7c00u).toUShort()
    if (e <= 0) {
        if (e < -10) return sign.toUShort()
        mantissa = mantissa or 0x800000u
        val shift = 14 - e
        var half = mantissa shr shift
        val rem = mantissa and ((1u shl shift) - 1u)
        val halfway = 1u shl (shift - 1)
        if (rem > halfway || (rem == halfway && (half and 1u) != 0u)) half++
        return (sign or half).toUShort()
    }
    var h = (e.toUInt() shl 10) or (mantissa shr 13)
    val r = mantissa and 0x1fffu
    if (r > 0x1000u || (r == 0x1000u && (h and 1u) != 0u)) h++
    return (sign or h).toUShort()
}
fun halfToFloat(half: UShort): Float {
    val h = half.toUInt()
    val sign = (h and 0x8000u) shl 16
    val exponent = (h shr 10) and 0x1fu
    var mantissa = h and 0x3ffu
    if (exponent == 0u) {
        if (mantissa == 0u) return Float.fromBits(sign.toInt())
        var e = -1
        do { ++e; mantissa = mantissa shl 1 } while ((mantissa and 0x400u) == 0u)
        return Float.fromBits((sign or ((127 - 15 - e).toUInt() shl 23) or ((mantissa and 0x3ffu) shl 13)).toInt())
    }
    if (exponent == 31u) return Float.fromBits((sign or 0x7f800000u or (mantissa shl 13)).toInt())
    return Float.fromBits((sign or ((exponent + 127u - 15u) shl 23) or (mantissa shl 13)).toInt())
}
/** Four [0, 1] floats into 8 bits each, x in the lowest byte. */
fun packUnorm4x8(v: Vec4): UInt = (roundAwayToInt(clamp(v.x, 0f, 1f) * 255f).toUInt() shl 0) or (roundAwayToInt(clamp(v.y, 0f, 1f) * 255f).toUInt() shl 8) or (roundAwayToInt(clamp(v.z, 0f, 1f) * 255f).toUInt() shl 16) or (roundAwayToInt(clamp(v.w, 0f, 1f) * 255f).toUInt() shl 24)
fun unpackUnorm4x8(p: UInt): Vec4 = Vec4(((p shr 0) and 0xffu).toFloat() / 255f, ((p shr 8) and 0xffu).toFloat() / 255f, ((p shr 16) and 0xffu).toFloat() / 255f, ((p shr 24) and 0xffu).toFloat() / 255f)
/** Four [-1, 1] floats into 8 signed bits each. */
fun packSnorm4x8(v: Vec4): UInt = ((roundAwayToInt(clamp(v.x, -1f, 1f) * 127f).toUInt() and 0xffu) shl 0) or ((roundAwayToInt(clamp(v.y, -1f, 1f) * 127f).toUInt() and 0xffu) shl 8) or ((roundAwayToInt(clamp(v.z, -1f, 1f) * 127f).toUInt() and 0xffu) shl 16) or ((roundAwayToInt(clamp(v.w, -1f, 1f) * 127f).toUInt() and 0xffu) shl 24)
fun unpackSnorm4x8(p: UInt): Vec4 = Vec4(clamp((p shr 0).toByte().toFloat() / 127f, -1f, 1f), clamp((p shr 8).toByte().toFloat() / 127f, -1f, 1f), clamp((p shr 16).toByte().toFloat() / 127f, -1f, 1f), clamp((p shr 24).toByte().toFloat() / 127f, -1f, 1f))
/** Two [0, 1] floats into 16 bits each. */
fun packUnorm2x16(v: Vec2): UInt = roundAwayToInt(clamp(v.x, 0f, 1f) * 65535f).toUInt() or (roundAwayToInt(clamp(v.y, 0f, 1f) * 65535f).toUInt() shl 16)
fun unpackUnorm2x16(p: UInt): Vec2 = Vec2((p and 0xffffu).toFloat() / 65535f, (p shr 16).toFloat() / 65535f)
/** Two [-1, 1] floats into 16 signed bits each. */
fun packSnorm2x16(v: Vec2): UInt = (roundAwayToInt(clamp(v.x, -1f, 1f) * 32767f).toUInt() and 0xffffu) or ((roundAwayToInt(clamp(v.y, -1f, 1f) * 32767f).toUInt() and 0xffffu) shl 16)
fun unpackSnorm2x16(p: UInt): Vec2 = Vec2(clamp(p.toShort().toFloat() / 32767f, -1f, 1f), clamp((p shr 16).toShort().toFloat() / 32767f, -1f, 1f))
/** Two floats as halves, x in the low 16 bits. */
fun packHalf2x16(v: Vec2): UInt = floatToHalf(v.x).toUInt() or (floatToHalf(v.y).toUInt() shl 16)
fun unpackHalf2x16(p: UInt): Vec2 = Vec2(halfToFloat(p.toUShort()), halfToFloat((p shr 16).toUShort()))
/** A double from its bits as two uints, low first. */
fun packDouble2x32(v: UVec2): Double = Double.fromBits((v.x.toULong() or (v.y.toULong() shl 32)).toLong())
fun unpackDouble2x32(d: Double): UVec2 {
    val b = d.toRawBits().toULong()
    return UVec2(b.toUInt(), (b shr 32).toUInt())
}

