/** The unsigned angle between two vectors, in radians. */
fun angle(a: Vec2, b: Vec2): Float {
    val denom = kotlin.math.sqrt((length2(a) * length2(b)))
    return (if ((denom > 0f)) kotlin.math.acos(clamp((dot(a, b) / denom), -1f, 1f)) else 0f)
}
fun angle(a: Vec3, b: Vec3): Float {
    val denom = kotlin.math.sqrt((length2(a) * length2(b)))
    return (if ((denom > 0f)) kotlin.math.acos(clamp((dot(a, b) / denom), -1f, 1f)) else 0f)
}
fun angle(a: Vec4, b: Vec4): Float {
    val denom = kotlin.math.sqrt((length2(a) * length2(b)))
    return (if ((denom > 0f)) kotlin.math.acos(clamp((dot(a, b) / denom), -1f, 1f)) else 0f)
}
fun angle(a: DVec2, b: DVec2): Double {
    val denom = kotlin.math.sqrt((length2(a) * length2(b)))
    return (if ((denom > 0.0)) kotlin.math.acos(clamp((dot(a, b) / denom), -1.0, 1.0)) else 0.0)
}
fun angle(a: DVec3, b: DVec3): Double {
    val denom = kotlin.math.sqrt((length2(a) * length2(b)))
    return (if ((denom > 0.0)) kotlin.math.acos(clamp((dot(a, b) / denom), -1.0, 1.0)) else 0.0)
}
fun angle(a: DVec4, b: DVec4): Double {
