    return (if ((denom > 0.0)) kotlin.math.acos(clamp((dot(a, b) / denom), -1.0, 1.0)) else 0.0)
}
/** The angle from a to b, positive counter-clockwise. */
fun orientedAngle(a: Vec2, b: Vec2): Float = kotlin.math.atan2(cross(a, b), dot(a, b))
fun orientedAngle(a: DVec2, b: DVec2): Double = kotlin.math.atan2(cross(a, b), dot(a, b))
/** The angle from a to b around axis: positive when counter-clockwise looking down the axis. */
fun orientedAngle(a: Vec3, b: Vec3, axis: Vec3): Float = kotlin.math.atan2(dot(cross(a, b), axis), dot(a, b))
fun orientedAngle(a: DVec3, b: DVec3, axis: DVec3): Double = kotlin.math.atan2(dot(cross(a, b), axis), dot(a, b))
/** The part of x along direction. */
fun proj(x: Vec2, direction: Vec2): Vec2 {
    val sq = dot(direction, direction)
    return (if ((sq > 0f)) (direction * (dot(x, direction) / sq)) else Vec2(0f))
}
fun proj(x: Vec3, direction: Vec3): Vec3 {
    val sq = dot(direction, direction)
    return (if ((sq > 0f)) (direction * (dot(x, direction) / sq)) else Vec3(0f))
}
fun proj(x: Vec4, direction: Vec4): Vec4 {
    val sq = dot(direction, direction)
    return (if ((sq > 0f)) (direction * (dot(x, direction) / sq)) else Vec4(0f))
}
fun proj(x: DVec2, direction: DVec2): DVec2 {
    val sq = dot(direction, direction)
    return (if ((sq > 0.0)) (direction * (dot(x, direction) / sq)) else DVec2(0.0))
}
fun proj(x: DVec3, direction: DVec3): DVec3 {
    val sq = dot(direction, direction)
    return (if ((sq > 0.0)) (direction * (dot(x, direction) / sq)) else DVec3(0.0))
}
fun proj(x: DVec4, direction: DVec4): DVec4 {
    val sq = dot(direction, direction)
    return (if ((sq > 0.0)) (direction * (dot(x, direction) / sq)) else DVec4(0.0))
}
/** The part of x perpendicular to direction. */
fun perp(x: Vec2, direction: Vec2): Vec2 = (x - proj(x, direction))
fun perp(x: Vec3, direction: Vec3): Vec3 = (x - proj(x, direction))
fun perp(x: Vec4, direction: Vec4): Vec4 = (x - proj(x, direction))
fun perp(x: DVec2, direction: DVec2): DVec2 = (x - proj(x, direction))
fun perp(x: DVec3, direction: DVec3): DVec3 = (x - proj(x, direction))
fun perp(x: DVec4, direction: DVec4): DVec4 = (x - proj(x, direction))
/** x made perpendicular to (normalised) y, and normalised. */
fun orthonormalize(x: Vec2, y: Vec2): Vec2 = normalize((x - (y * dot(y, x))))
fun orthonormalize(x: Vec3, y: Vec3): Vec3 = normalize((x - (y * dot(y, x))))
fun orthonormalize(x: Vec4, y: Vec4): Vec4 = normalize((x - (y * dot(y, x))))
fun orthonormalize(x: DVec2, y: DVec2): DVec2 = normalize((x - (y * dot(y, x))))
fun orthonormalize(x: DVec3, y: DVec3): DVec3 = normalize((x - (y * dot(y, x))))
fun orthonormalize(x: DVec4, y: DVec4): DVec4 = normalize((x - (y * dot(y, x))))
/** The unit normal of a triangle, counter-clockwise front. */
fun triangleNormal(a: Vec3, b: Vec3, c: Vec3): Vec3 = normalize(cross((b - a), (c - a)))
fun triangleNormal(a: DVec3, b: DVec3, c: DVec3): DVec3 = normalize(cross((b - a), (c - a)))
/** A Euclidean vector as (latitude, longitude, length). */
fun polar(euclidean: Vec3): Vec3 {
    val len = length(euclidean)
    val n = (euclidean / len)
    return Vec3(kotlin.math.asin(clamp(n.y, -1f, 1f)), kotlin.math.atan2(n.x, n.z), len)
}
fun polar(euclidean: DVec3): DVec3 {
    val len = length(euclidean)
    val n = (euclidean / len)
    return DVec3(kotlin.math.asin(clamp(n.y, -1.0, 1.0)), kotlin.math.atan2(n.x, n.z), len)
}
/** A unit vector from (latitude, longitude). */
fun euclidean(polar: Vec2): Vec3 {
    val lat = polar.x
    val lon = polar.y
    return Vec3((kotlin.math.cos(lat) * kotlin.math.sin(lon)), kotlin.math.sin(lat), (kotlin.math.cos(lat) * kotlin.math.cos(lon)))
}
fun euclidean(polar: DVec2): DVec3 {
    val lat = polar.x
    val lon = polar.y
    return DVec3((kotlin.math.cos(lat) * kotlin.math.sin(lon)), kotlin.math.sin(lat), (kotlin.math.cos(lat) * kotlin.math.cos(lon)))
}
/** v turned angle radians counter-clockwise. */
fun rotate(v: Vec2, angle: Float): Vec2 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return Vec2(((v.x * c) - (v.y * s)), ((v.x * s) + (v.y * c)))
}
fun rotate(v: DVec2, angle: Double): DVec2 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return DVec2(((v.x * c) - (v.y * s)), ((v.x * s) + (v.y * c)))
}
fun rotateX(v: Vec3, angle: Float): Vec3 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return Vec3(v.x, ((v.y * c) - (v.z * s)), ((v.y * s) + (v.z * c)))
}
fun rotateX(v: DVec3, angle: Double): DVec3 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return DVec3(v.x, ((v.y * c) - (v.z * s)), ((v.y * s) + (v.z * c)))
}
fun rotateY(v: Vec3, angle: Float): Vec3 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return Vec3(((v.x * c) + (v.z * s)), v.y, ((-v.x * s) + (v.z * c)))
}
fun rotateY(v: DVec3, angle: Double): DVec3 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return DVec3(((v.x * c) + (v.z * s)), v.y, ((-v.x * s) + (v.z * c)))
}
fun rotateZ(v: Vec3, angle: Float): Vec3 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return Vec3(((v.x * c) - (v.y * s)), ((v.x * s) + (v.y * c)), v.z)
}
fun rotateZ(v: DVec3, angle: Double): DVec3 {
    val c = kotlin.math.cos(angle)
    val s = kotlin.math.sin(angle)
    return DVec3(((v.x * c) - (v.y * s)), ((v.x * s) + (v.y * c)), v.z)
}
/** Normalize, or fallback when v is (nearly) zero. */
fun normalizeOr(v: Vec2, fallback: Vec2): Vec2 {
    val len = length(v)
    return (if ((len > 1.1920929E-07f)) (v * (1f / len)) else fallback)
}
fun normalizeOr(v: Vec3, fallback: Vec3): Vec3 {
    val len = length(v)
    return (if ((len > 1.1920929E-07f)) (v * (1f / len)) else fallback)
}
fun normalizeOr(v: Vec4, fallback: Vec4): Vec4 {
    val len = length(v)
    return (if ((len > 1.1920929E-07f)) (v * (1f / len)) else fallback)
}
fun normalizeOr(v: DVec2, fallback: DVec2): DVec2 {
    val len = length(v)
    return (if ((len > 2.220446049250313E-16)) (v * (1.0 / len)) else fallback)
}
fun normalizeOr(v: DVec3, fallback: DVec3): DVec3 {
    val len = length(v)
    return (if ((len > 2.220446049250313E-16)) (v * (1.0 / len)) else fallback)
}
fun normalizeOr(v: DVec4, fallback: DVec4): DVec4 {
    val len = length(v)
    return (if ((len > 2.220446049250313E-16)) (v * (1.0 / len)) else fallback)
}
/** v with its length capped at maxLength. */
fun clampLength(v: Vec2, maxLength: Float): Vec2 {
    val sq = length2(v)
    return (if ((sq > (maxLength * maxLength))) (v * (maxLength / kotlin.math.sqrt(sq))) else v)
}
