/** A unit vector perpendicular to v (any one). */
fun anyPerpendicular(v: Vec3): Vec3 {
    val other = (if ((abs(v.x) < 0.9f)) Vec3(1f, 0f, 0f) else Vec3(0f, 1f, 0f))
    return normalize(cross(v, other))
}
fun anyPerpendicular(v: DVec3): DVec3 {
    val other = (if ((abs(v.x) < 0.9)) DVec3(1.0, 0.0, 0.0) else DVec3(0.0, 1.0, 0.0))
    return normalize(cross(v, other))
}
/** current moved toward target by at most maxDelta, never past it. */
fun moveTowards(current: Float, target: Float, maxDelta: Float): Float = (if ((abs((target - current)) <= maxDelta)) target else (current + (sign((target - current)) * maxDelta)))
fun moveTowards(current: Double, target: Double, maxDelta: Double): Double = (if ((abs((target - current)) <= maxDelta)) target else (current + (sign((target - current)) * maxDelta)))
/** The vector form: along a straight line. */
fun moveTowards(current: Vec2, target: Vec2, maxDistance: Float): Vec2 {
    val d = (target - current)
    val len = length(d)
    return (if (((len <= maxDistance) || (len == 0f))) target else (current + (d * (maxDistance / len))))
}
fun moveTowards(current: Vec3, target: Vec3, maxDistance: Float): Vec3 {
    val d = (target - current)
    val len = length(d)
