/** The shortest signed difference between two angles in radians, in [-Pi, Pi]. */
fun deltaAngle(fromAngle: Float, toAngle: Float): Float {
    val d = mod((toAngle - fromAngle), Tau)
    return (if ((d > Pi)) (d - Tau) else d)
}
fun deltaAngle(fromAngle: Double, toAngle: Double): Double {
    val d = mod((toAngle - fromAngle), DTau)
    return (if ((d > DPi)) (d - DTau) else d)
}
/** An angle wrapped into [-Pi, Pi). */
fun wrapAngle(radians: Float): Float = (mod((radians + Pi), Tau) - Pi)
fun wrapAngle(radians: Double): Double = (mod((radians + DPi), DTau) - DPi)
/** A critically damped spring toward target: frame-rate independent, never overshoots. velocity is its state. */
fun smoothDamp(current: Float, target: Float, velocity: Ref<Float>, smoothTime: Float, deltaTime: Float, maxSpeed: Float = Float.POSITIVE_INFINITY): Float {
    val st = max(0.0001f, smoothTime)
    val omega = 2f / st
    val x = omega * deltaTime
    val exp = 1f / (1f + x + 0.48f * x * x + 0.235f * x * x * x)
    val maxChange = maxSpeed * st
    val change = clamp(current - target, -maxChange, maxChange)
    val clampedTarget = current - change
    val temp = (velocity.value + omega * change) * deltaTime
    velocity.value = (velocity.value - omega * temp) * exp
    var output = clampedTarget + (change + temp) * exp
    if ((target - current > 0f) == (output > target)) { output = target; velocity.value = (output - target) / deltaTime }
    return output
}
fun smoothDamp(current: Double, target: Double, velocity: Ref<Double>, smoothTime: Double, deltaTime: Double, maxSpeed: Double = Double.POSITIVE_INFINITY): Double {
    val st = max(0.0001, smoothTime)
    val omega = 2.0 / st
    val x = omega * deltaTime
    val exp = 1.0 / (1.0 + x + 0.48 * x * x + 0.235 * x * x * x)
    val maxChange = maxSpeed * st
    val change = clamp(current - target, -maxChange, maxChange)
    val clampedTarget = current - change
    val temp = (velocity.value + omega * change) * deltaTime
    velocity.value = (velocity.value - omega * temp) * exp
    var output = clampedTarget + (change + temp) * exp
    if ((target - current > 0.0) == (output > target)) { output = target; velocity.value = (output - target) / deltaTime }
    return output
}
