// ---- matrices (kmath/matrix.h) ----------------------------------------------------------------------------

fun transpose(m: Mat2): Mat2 = Mat2(Vec2(m[0, 0], m[1, 0]), Vec2(m[0, 1], m[1, 1]))
fun matrixCompMult(a: Mat2, b: Mat2): Mat2 = Mat2(a[0] * b[0], a[1] * b[1])
fun outerProduct(column: Vec2, row: Vec2): Mat2 = Mat2(column * row.x, column * row.y)
fun row(m: Mat2, r: Int): Vec2 = m.row(r)
fun column(m: Mat2, c: Int): Vec2 = m[c]
fun row(m: Mat2, r: Int, value: Vec2): Mat2 = m.with(0, r, value.x).with(1, r, value.y)
fun column(m: Mat2, c: Int, value: Vec2): Mat2 = m.withColumn(c, value)
fun approxEqual(a: Mat2, b: Mat2, epsilon: Float = Epsilon) = approxEqual(a[0], b[0], epsilon) && approxEqual(a[1], b[1], epsilon)
fun diagonal(v: Vec2): Mat2 = Mat2(Vec2(v.x, 0f), Vec2(0f, v.y))
fun determinant(m: Mat2): Float = m[0, 0] * m[1, 1] - m[1, 0] * m[0, 1]
fun inverse(m: Mat2): Mat2 {
    val inv = 1f / determinant(m)
    return Mat2(Vec2(m[1, 1] * inv, -m[0, 1] * inv), Vec2(-m[1, 0] * inv, m[0, 0] * inv))
}
fun transpose(m: Mat2x3): Mat3x2 = Mat3x2(Vec2(m[0, 0], m[1, 0]), Vec2(m[0, 1], m[1, 1]), Vec2(m[0, 2], m[1, 2]))
fun matrixCompMult(a: Mat2x3, b: Mat2x3): Mat2x3 = Mat2x3(a[0] * b[0], a[1] * b[1])
fun outerProduct(column: Vec3, row: Vec2): Mat2x3 = Mat2x3(column * row.x, column * row.y)
fun row(m: Mat2x3, r: Int): Vec2 = m.row(r)
fun column(m: Mat2x3, c: Int): Vec3 = m[c]
fun row(m: Mat2x3, r: Int, value: Vec2): Mat2x3 = m.with(0, r, value.x).with(1, r, value.y)
fun column(m: Mat2x3, c: Int, value: Vec3): Mat2x3 = m.withColumn(c, value)
fun approxEqual(a: Mat2x3, b: Mat2x3, epsilon: Float = Epsilon) = approxEqual(a[0], b[0], epsilon) && approxEqual(a[1], b[1], epsilon)
fun transpose(m: Mat2x4): Mat4x2 = Mat4x2(Vec2(m[0, 0], m[1, 0]), Vec2(m[0, 1], m[1, 1]), Vec2(m[0, 2], m[1, 2]), Vec2(m[0, 3], m[1, 3]))
fun matrixCompMult(a: Mat2x4, b: Mat2x4): Mat2x4 = Mat2x4(a[0] * b[0], a[1] * b[1])
fun outerProduct(column: Vec4, row: Vec2): Mat2x4 = Mat2x4(column * row.x, column * row.y)
fun row(m: Mat2x4, r: Int): Vec2 = m.row(r)
fun column(m: Mat2x4, c: Int): Vec4 = m[c]
fun row(m: Mat2x4, r: Int, value: Vec2): Mat2x4 = m.with(0, r, value.x).with(1, r, value.y)
fun column(m: Mat2x4, c: Int, value: Vec4): Mat2x4 = m.withColumn(c, value)
fun approxEqual(a: Mat2x4, b: Mat2x4, epsilon: Float = Epsilon) = approxEqual(a[0], b[0], epsilon) && approxEqual(a[1], b[1], epsilon)
fun transpose(m: Mat3x2): Mat2x3 = Mat2x3(Vec3(m[0, 0], m[1, 0], m[2, 0]), Vec3(m[0, 1], m[1, 1], m[2, 1]))
fun matrixCompMult(a: Mat3x2, b: Mat3x2): Mat3x2 = Mat3x2(a[0] * b[0], a[1] * b[1], a[2] * b[2])
