fun matrixCompMult(a: DMat4, b: DMat4): DMat4 = DMat4(a[0] * b[0], a[1] * b[1], a[2] * b[2], a[3] * b[3])
fun outerProduct(column: DVec4, row: DVec4): DMat4 = DMat4(column * row.x, column * row.y, column * row.z, column * row.w)
fun row(m: DMat4, r: Int): DVec4 = m.row(r)
fun column(m: DMat4, c: Int): DVec4 = m[c]
fun row(m: DMat4, r: Int, value: DVec4): DMat4 = m.with(0, r, value.x).with(1, r, value.y).with(2, r, value.z).with(3, r, value.w)
fun column(m: DMat4, c: Int, value: DVec4): DMat4 = m.withColumn(c, value)
fun approxEqual(a: DMat4, b: DMat4, epsilon: Double = DEpsilon) = approxEqual(a[0], b[0], epsilon) && approxEqual(a[1], b[1], epsilon) && approxEqual(a[2], b[2], epsilon) && approxEqual(a[3], b[3], epsilon)
fun diagonal(v: DVec4): DMat4 = DMat4(DVec4(v.x, 0.0, 0.0, 0.0), DVec4(0.0, v.y, 0.0, 0.0), DVec4(0.0, 0.0, v.z, 0.0), DVec4(0.0, 0.0, 0.0, v.w))
fun determinant(m: DMat4): Double {
    val s0 = m[2, 2] * m[3, 3] - m[3, 2] * m[2, 3]
    val s1 = m[2, 1] * m[3, 3] - m[3, 1] * m[2, 3]
    val s2 = m[2, 1] * m[3, 2] - m[3, 1] * m[2, 2]
    val s3 = m[2, 0] * m[3, 3] - m[3, 0] * m[2, 3]
    val s4 = m[2, 0] * m[3, 2] - m[3, 0] * m[2, 2]
    val s5 = m[2, 0] * m[3, 1] - m[3, 0] * m[2, 1]
    val c0 = (m[1, 1] * s0 - m[1, 2] * s1 + m[1, 3] * s2)
    val c1 = -(m[1, 0] * s0 - m[1, 2] * s3 + m[1, 3] * s4)
    val c2 = (m[1, 0] * s1 - m[1, 1] * s3 + m[1, 3] * s5)
    val c3 = -(m[1, 0] * s2 - m[1, 1] * s4 + m[1, 2] * s5)
    return m[0, 0] * c0 + m[0, 1] * c1 + m[0, 2] * c2 + m[0, 3] * c3
}
fun inverse(m: DMat4): DMat4 {
    val a2323 = m[2, 2] * m[3, 3] - m[2, 3] * m[3, 2]
    val a1323 = m[2, 1] * m[3, 3] - m[2, 3] * m[3, 1]
    val a1223 = m[2, 1] * m[3, 2] - m[2, 2] * m[3, 1]
    val a0323 = m[2, 0] * m[3, 3] - m[2, 3] * m[3, 0]
    val a0223 = m[2, 0] * m[3, 2] - m[2, 2] * m[3, 0]
    val a0123 = m[2, 0] * m[3, 1] - m[2, 1] * m[3, 0]
    val a2313 = m[1, 2] * m[3, 3] - m[1, 3] * m[3, 2]
    val a1313 = m[1, 1] * m[3, 3] - m[1, 3] * m[3, 1]
    val a1213 = m[1, 1] * m[3, 2] - m[1, 2] * m[3, 1]
    val a2312 = m[1, 2] * m[2, 3] - m[1, 3] * m[2, 2]
    val a1312 = m[1, 1] * m[2, 3] - m[1, 3] * m[2, 1]
    val a1212 = m[1, 1] * m[2, 2] - m[1, 2] * m[2, 1]
    val a0313 = m[1, 0] * m[3, 3] - m[1, 3] * m[3, 0]
    val a0213 = m[1, 0] * m[3, 2] - m[1, 2] * m[3, 0]
    val a0312 = m[1, 0] * m[2, 3] - m[1, 3] * m[2, 0]
    val a0212 = m[1, 0] * m[2, 2] - m[1, 2] * m[2, 0]
    val a0113 = m[1, 0] * m[3, 1] - m[1, 1] * m[3, 0]
    val a0112 = m[1, 0] * m[2, 1] - m[1, 1] * m[2, 0]
    val det = m[0, 0] * (m[1, 1] * a2323 - m[1, 2] * a1323 + m[1, 3] * a1223) - m[0, 1] * (m[1, 0] * a2323 - m[1, 2] * a0323 + m[1, 3] * a0223) + m[0, 2] * (m[1, 0] * a1323 - m[1, 1] * a0323 + m[1, 3] * a0123) - m[0, 3] * (m[1, 0] * a1223 - m[1, 1] * a0223 + m[1, 2] * a0123)
    val inv = 1.0 / det
    return DMat4(DVec4(inv * (m[1, 1] * a2323 - m[1, 2] * a1323 + m[1, 3] * a1223), inv * -(m[0, 1] * a2323 - m[0, 2] * a1323 + m[0, 3] * a1223), inv * (m[0, 1] * a2313 - m[0, 2] * a1313 + m[0, 3] * a1213), inv * -(m[0, 1] * a2312 - m[0, 2] * a1312 + m[0, 3] * a1212)), DVec4(inv * -(m[1, 0] * a2323 - m[1, 2] * a0323 + m[1, 3] * a0223), inv * (m[0, 0] * a2323 - m[0, 2] * a0323 + m[0, 3] * a0223), inv * -(m[0, 0] * a2313 - m[0, 2] * a0313 + m[0, 3] * a0213), inv * (m[0, 0] * a2312 - m[0, 2] * a0312 + m[0, 3] * a0212)), DVec4(inv * (m[1, 0] * a1323 - m[1, 1] * a0323 + m[1, 3] * a0123), inv * -(m[0, 0] * a1323 - m[0, 1] * a0323 + m[0, 3] * a0123), inv * (m[0, 0] * a1313 - m[0, 1] * a0313 + m[0, 3] * a0113), inv * -(m[0, 0] * a1312 - m[0, 1] * a0312 + m[0, 3] * a0112)), DVec4(inv * -(m[1, 0] * a1223 - m[1, 1] * a0223 + m[1, 2] * a0123), inv * (m[0, 0] * a1223 - m[0, 1] * a0223 + m[0, 2] * a0123), inv * -(m[0, 0] * a1213 - m[0, 1] * a0213 + m[0, 2] * a0113), inv * (m[0, 0] * a1212 - m[0, 1] * a0212 + m[0, 2] * a0112)))
}
fun normalMatrix(model: DMat4): DMat3 = transpose(inverse(DMat3(model)))

// ---- Euler angles by name (kmath/euler.h): eulerAngleXYZ(a, b, c) is X(a) * Y(b) * Z(c) ----------------

fun eulerAngleXY(first: Float, second: Float): Mat4 = axisRotation(0, first) * axisRotation(1, second)
fun eulerAngleXZ(first: Float, second: Float): Mat4 = axisRotation(0, first) * axisRotation(2, second)
fun eulerAngleYX(first: Float, second: Float): Mat4 = axisRotation(1, first) * axisRotation(0, second)
fun eulerAngleYZ(first: Float, second: Float): Mat4 = axisRotation(1, first) * axisRotation(2, second)
fun eulerAngleZX(first: Float, second: Float): Mat4 = axisRotation(2, first) * axisRotation(0, second)
fun eulerAngleZY(first: Float, second: Float): Mat4 = axisRotation(2, first) * axisRotation(1, second)
fun eulerAngleXYZ(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.XYZ, Vec3(first, second, third))
fun extractEulerAngleXYZ(m: Mat4): Vec3 = extractEulerAngles(EulerOrder.XYZ, m)
fun eulerAngleXZY(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.XZY, Vec3(first, second, third))
fun extractEulerAngleXZY(m: Mat4): Vec3 = extractEulerAngles(EulerOrder.XZY, m)
