fun eulerAngleYZX(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.YZX, Vec3(first, second, third))
fun extractEulerAngleYZX(m: Mat4): Vec3 = extractEulerAngles(EulerOrder.YZX, m)
fun eulerAngleZXY(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.ZXY, Vec3(first, second, third))
fun extractEulerAngleZXY(m: Mat4): Vec3 = extractEulerAngles(EulerOrder.ZXY, m)
fun eulerAngleZYX(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.ZYX, Vec3(first, second, third))
fun extractEulerAngleZYX(m: Mat4): Vec3 = extractEulerAngles(EulerOrder.ZYX, m)
fun eulerAngleXYX(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.XYX, Vec3(first, second, third))
fun extractEulerAngleXYX(m: Mat4): Vec3 = extractEulerAngles(EulerOrder.XYX, m)
fun eulerAngleXZX(first: Float, second: Float, third: Float): Mat4 = eulerAngles(EulerOrder.XZX, Vec3(first, second, third))
